const vulnResolveFindings = `-- name: VulnResolveFindings :many
WITH old AS (
    SELECT id, status FROM vuln_finding WHERE id = ANY($2::text[]::uuid[]) AND status <> 'resolved' FOR UPDATE
)
UPDATE vuln_finding f
   SET status = 'resolved', status_before_resolution = old.status, resolved_reason = $1::text, resolved_at = now(),
       status_changed_at = now(), status_changed_by = NULL, revision = f.revision + 1
  FROM old
 WHERE f.id = old.id
RETURNING f.id::text AS id, old.status::text AS old_status
`

type VulnResolveFindingsParams struct {
	Reason string
	Ids    []string
}

type VulnResolveFindingsRow struct {
	ID        string
	OldStatus string
}

// trove resolves findings: the previous status is kept in status_before_resolution. Only a finding that is not resolved yet
// changes, so a batch retried after a lost commit changes nothing the second time. The old status is returned for the events.
func (q *Queries) VulnResolveFindings(ctx context.Context, arg VulnResolveFindingsParams) ([]VulnResolveFindingsRow, error) {
	rows, err := q.db.Query(ctx, vulnResolveFindings, arg.Reason, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VulnResolveFindingsRow{}
	for rows.Next() {
		var i VulnResolveFindingsRow
		if err := rows.Scan(&i.ID, &i.OldStatus); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const vulnResolveRemovedVersions = `-- name: VulnResolveRemovedVersions :many
WITH old AS (
    SELECT f.id, f.status FROM vuln_finding f
     WHERE f.version_id = ANY($1::bigint[]) AND f.status <> 'resolved'
       AND NOT EXISTS (SELECT 1 FROM package_versions pv
                        WHERE pv.id = f.version_id
                          AND (EXISTS (SELECT 1 FROM items l WHERE l.id = pv.lead_item_id)
                               OR (pv.lead_item_id IS NULL AND EXISTS (SELECT 1 FROM items i WHERE i.version_id = pv.id AND i.kind = 'file'))))
       FOR UPDATE OF f
)
UPDATE vuln_finding f
   SET status = 'resolved', status_before_resolution = old.status, resolved_reason = 'version_removed', resolved_at = now(),
       status_changed_at = now(), status_changed_by = NULL, revision = f.revision + 1
  FROM old
 WHERE f.id = old.id
RETURNING f.id::text AS id, old.status::text AS old_status
`

type VulnResolveRemovedVersionsRow struct {
	ID        string
	OldStatus string
}

// Removal of versions (R-VULN-011): the findings of a version whose lead item is gone resolve with version_removed. The hook runs
// before the format deletes the version row, in the removing transaction, when the removed items are gone already. A version
// that keeps its lead item (a removed companion file only) keeps its findings; one without a lead item is removed when it has
// no file left.
func (q *Queries) VulnResolveRemovedVersions(ctx context.Context, versionIds []int64) ([]VulnResolveRemovedVersionsRow, error) {
	rows, err := q.db.Query(ctx, vulnResolveRemovedVersions, versionIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VulnResolveRemovedVersionsRow{}
	for rows.Next() {
		var i VulnResolveRemovedVersionsRow
		if err := rows.Scan(&i.ID, &i.OldStatus); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

